  "jungle.scene6": "Je vindt een gewonde vogel. Wat doe je?",
  "jungle.s6c1": "Draag hem voorzichtig — het kan je naar een pad leiden (+5 HP, +25 pnt)",
  "jungle.s6c2": "Laat hem achter — zorgen kosten energie (0 HP, +10 pnt)",
  "jungle.scene7": "Een rivier blokkeert je pad. Het water ziet er snel uit.",
  "jungle.s7c1": "Bouw een vlot van omgevallen boomstammen (−5 HP, +40 pnt)",
  "jungle.s7c2": "Loop stroomopwaarts om een ondiepe oversteek te vinden (+10 HP, +20 pnt)",
  "jungle.scene8": "Je ziet rook in de verte.",
  "jungle.s8c1": "Ga naar de rook — misschien redding! (+15 HP, +45 pnt)",
  "jungle.s8c2": "Vermijd het — misschien een bosbrand (−5 HP, +15 pnt)",
  "jungle.scene9": "Het wordt nacht. Je hebt onderdak nodig.",
  "jungle.s9c1": "Klim in een hoge boom om veilig te blijven voor roofdieren (+10 HP, +30 pnt)",
  "jungle.s9c2": "Bouw een schuilplek op de grond met takken (−5 HP, +35 pnt)",
  "jungle.scene10": "Je vindt een vrucht die je niet herkent. Je hebt het erg honger.",
  "jungle.s10c1": "Eet hem — je bent uitgehongerd! (−20 HP, +30 pnt)",
  "jungle.s10c2": "Test eerst een klein stukje op je huid (0 HP, +20 pnt)",
  "jungle.scene11": "Een grote slang kronkelt op het pad.",
  "jungle.s11c1": "Stap langzaam achteruit en zoek een omweg (+5 HP, +30 pnt)",
  "jungle.s11c2": "Probeer hem weg te jagen (−25 HP, +40 pnt)",
  "jungle.scene12": "Je hoort een waterval — je watervoorraad is kritiek laag.",
  "jungle.s12c1": "Volg het geluid om vers water te vinden (+20 HP, +35 pnt)",
  "jungle.s12c2": "Negeer het en blijf vooruitgaan (−15 HP, +20 pnt)",
  "jungle.scene13": "Er komt snel een storm op je af.",
  "jungle.s13c1": "Zoek hoger gelegen grond en dekking (+10 HP, +25 pnt)",
  "jungle.s13c2": "Blijf bewegen om eraan te ontsnappen (−10 HP, +30 pnt)",
  "jungle.scene14": "Je vindt een grot. Het wordt donkerder.",
  "jungle.s14c1": "Ga de grot in voor onderdak (+15 HP, +30 pnt)",
  "jungle.s14c2": "Slaap onder een boom — de grot is misschien bezet (+5 HP, +20 pnt)",
  "jungle.scene15": "Je bent uitgeput. Een open plek voor je ziet er veilig uit.",
  "jungle.s15c1": "Rust uit en kom bij (+20 HP, +20 pnt)",
  "jungle.s15c2": "Ga door — rust is hier gevaarlijk (−5 HP, +30 pnt)",
  "jungle.scene16": "Je vindt een oude kaart die in een boom is gegraveerd.",
  "jungle.s16c1": "Volg de richting van de kaart (+5 HP, +40 pnt)",
  "jungle.s16c2": "Negeer het — het kan verouderd zijn (0 HP, +10 pnt)",
  "jungle.scene17": "Wilde zwijnen steken agressief je pad over.",
  "jungle.s17c1": "Klim meteen in de dichtstbijzijnde boom (+5 HP, +30 pnt)",
  "jungle.s17c2": "Blijf staan en schreeuw (−20 HP, +35 pnt)",
  "jungle.scene18": "Je vindt een verlaten kamp met voorraden.",
  "jungle.s18c1": "Neem alles wat nuttig is (+20 HP, +50 pnt)",
  "jungle.s18c2": "Laat maar — iemand heeft het later misschien nodig (0 HP, +10 pts)",
  "jungle.scene19": "Een aap steelt je voedselzak!",
  "jungle.s19c1": "Jaag de aap weg (−10 HP, +40 pts)",
  "jungle.s19c2": "Laat gaan — het kost te veel energie (+0 HP, +15 pts)",
  "jungle.scene20": "Je hoort een helikopter overvliegen.",
  "jungle.s20c1": "Steek meteen een signaalsvuur aan! (+30 HP, +60 pts)",
  "jungle.s20c2": "Sla met je armen — misschien ziet hij je (+5 HP, +40 pts)",
